                      "max_rel_rms": max(c["output"]["rel_rms"] for c in correctness),
                      "min_cosine": min(c["output"]["cosine_similarity"] for c in correctness),
                      "decomposition": decomposition, "scratch_bytes": scratch.nbytes}, indent=2))


